from ...templatesession import new_session
from ...exception import NonexistentBtssm
from .base_btssm import BaseBtssmInterface


class VersionsInterface(BaseBtssmInterface):
    """Keywords related to BTS SM versions."""

    def get_installed_btssm_versions(self, filter_expression='*', **kwargs):
        """Returns the list of installed BTS SM (Node Manager) versions matching given filter expression.

        :param string filter_expression: Expression used to filter available versions (passed to the ls command).

        :return: Installed BTSSM applications.
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        config = self.command_store.get(alias).get_config()
        with new_session.NewSession(alias, config) as session:
            return session.btssm.get_installed_versions(filter_expression)

    def get_newest_installed_btssm_version(self, filter_expression='*', **kwargs):
        """Returns the newest installed BTS SM (Node Manager) version.

        :param string filter_expression: Expression used to filter available versions (passed to the ls command).

        :return: Latest installed BTSSM version
        :rtype: string
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        config = self.command_store.get(alias).get_config()
        with new_session.NewSession(alias, config) as session:
            versions = session.btssm.get_installed_versions(filter_expression)
            if not versions:
                raise NonexistentBtssm("Btssm version not found")
            return max(versions)
